import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DCnq5n9u.js";var i=JSON.parse(`{"title":"高级配置","description":"","frontmatter":{"version":"2.1.10"},"headers":[],"relativePath":"guide/feature/advanced.md","filePath":"guide/feature/advanced.md","lastUpdated":1788751487000}`),a={name:`guide/feature/advanced.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="高级配置" tabindex="-1">高级配置 <a class="header-anchor" href="#高级配置" aria-label="Permalink to “高级配置”">​</a></h1><h2 id="_1-webhook-端点模式" tabindex="-1">1. Webhook 端点模式 <a class="header-anchor" href="#_1-webhook-端点模式" aria-label="Permalink to “1. Webhook 端点模式”">​</a></h2><p>添加机器人时，插件支持两种 Webhook 地址配置方式：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td>平台默认模式</td><td>选择平台后只输入 <code>Token</code> 或 <code>Key</code>，插件自动拼接官方 Webhook</td><td>官方 SaaS 地址，优先推荐</td></tr><tr><td>自定义 Webhook</td><td>直接粘贴完整 Webhook URL</td><td>已拿到完整地址、使用私有域名、历史配置迁移</td></tr></tbody></table><p>选择平台后，机器人编辑器会自动切换输入提示、预览最终 Webhook，并记录对应协议类型。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><code>Lark / 飞书</code> 支持自定义域名，只要 Webhook 路径仍为 <code>/open-apis/bot/v2/hook/{token}</code>。</p></div><p>不同平台的默认输入内容如下：</p><table tabindex="0"><thead><tr><th>平台</th><th>默认输入值</th><th>自动拼接结果</th></tr></thead><tbody><tr><td>Lark / 飞书</td><td>机器人 <code>Token</code></td><td><code>https://open.larksuite.com/open-apis/bot/v2/hook/{token}</code> 或 <code>https://open.feishu.cn/open-apis/bot/v2/hook/{token}</code></td></tr><tr><td>钉钉</td><td>机器人 <code>access_token</code></td><td><code>https://oapi.dingtalk.com/robot/send?access_token={token}</code></td></tr><tr><td>企业微信</td><td>群机器人 <code>key</code></td><td><code>https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key={key}</code></td></tr></tbody></table><h2 id="_2-安全策略" tabindex="-1">2. 安全策略 <a class="header-anchor" href="#_2-安全策略" aria-label="Permalink to “2. 安全策略”">​</a></h2><p>每个机器人都可配置以下安全策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>说明</th></tr></thead><tbody><tr><td><strong>关键词（KEY）</strong></td><td>设定后，只有包含关键词的消息内容才会被正常发送，多个值使用逗号分隔。</td></tr><tr><td><strong>签名密钥（SECRET）</strong></td><td>使用 HMAC-SHA256 对消息进行签名验证。需在机器人安全设置中获取密钥。</td></tr><tr><td><strong>禁用 SSL 验证（NO_SSL）</strong></td><td>禁用 Java HTTP 客户端中的 SSL/TLS 证书验证。</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>企业微信群机器人本身没有飞书 / 钉钉那种签名验签流程，但插件仍支持关键词校验与 SSL 控制等通用策略。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>禁用 SSL 验证会降低连接的安全性，可能导致中间人攻击等安全风险。建议仅在受控测试环境中使用此选项。</p></div><h2 id="_3-重试配置" tabindex="-1">3. 重试配置 <a class="header-anchor" href="#_3-重试配置" aria-label="Permalink to “3. 重试配置”">​</a></h2><p>插件支持对发送失败的 Webhook 消息进行重试，每个机器人可单独配置。默认不开启。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td><code>false</code></td><td>是否启用重试</td></tr><tr><td><code>maxAttempts</code></td><td>int</td><td><code>1</code></td><td>最大尝试次数（包含首次发送）</td></tr><tr><td><code>initialDelayMs</code></td><td>long</td><td><code>500</code></td><td>首次重试前的等待时间（毫秒）</td></tr><tr><td><code>maxDelayMs</code></td><td>long</td><td><code>5000</code></td><td>重试等待时间上限（毫秒）</td></tr><tr><td><code>backoffMultiplier</code></td><td>double</td><td><code>2.0</code></td><td>退避倍数（必须 &gt;= 1.0）</td></tr><tr><td><code>jitterRatio</code></td><td>double</td><td><code>0.2</code></td><td>等待时间抖动比例（0.0 ~ 1.0）</td></tr></tbody></table><p>重试采用指数退避策略，每次重试的等待时间 = 上次等待 × <code>backoffMultiplier</code>，并叠加随机抖动以避免请求风暴。</p><p>高级选项（<code>initialDelayMs</code>、<code>maxDelayMs</code>、<code>backoffMultiplier</code>、<code>jitterRatio</code>）默认折叠，点击「高级」可展开配置。</p><h2 id="_4-消息语言" tabindex="-1">4. 消息语言 <a class="header-anchor" href="#_4-消息语言" aria-label="Permalink to “4. 消息语言”">​</a></h2><p>每个机器人可独立设置消息语言，影响内置卡片标题和默认模板的显示语言。</p><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>中文</td><td>使用简体中文显示内置消息</td></tr><tr><td>EN</td><td>使用英文显示内置消息</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>仅影响内置卡片标题与默认模板，自定义消息内容不做翻译。</p></div><h3 id="_4-1-平台消息能力差异" tabindex="-1">4.1 平台消息能力差异 <a class="header-anchor" href="#_4-1-平台消息能力差异" aria-label="Permalink to “4.1 平台消息能力差异”">​</a></h3><p>插件对外统一暴露消息类型，但每个平台只接受其中一部分。传入平台不接受的类型会直接失败并给出提示。</p><table tabindex="0"><thead><tr><th>消息类型</th><th>Lark / 飞书</th><th>钉钉</th><th>企业微信</th></tr></thead><tbody><tr><td><code>TEXT</code></td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><code>MARKDOWN</code></td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><code>CARD</code></td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><code>IMAGE</code></td><td>✅</td><td>—</td><td>—</td></tr><tr><td><code>SHARE_CHAT</code></td><td>✅</td><td>—</td><td>—</td></tr><tr><td><code>POST</code></td><td>✅</td><td>—</td><td>⚠️ 按 <code>MARKDOWN</code> 发送</td></tr><tr><td><code>LINK</code></td><td>—</td><td>✅</td><td>⚠️ 按 <code>MARKDOWN</code> 发送</td></tr><tr><td><code>FEED_CARD</code></td><td>—</td><td>✅</td><td>—</td></tr></tbody></table><p>Lark / 飞书另外支持在 <code>Freestyle</code> 中粘贴自定义 JSON 卡片。</p><p>各平台参数的细节说明见对应的 Pipeline 页面：<a href="./lark/pipeline.html">Lark / 飞书</a>、<a href="./ding/pipeline.html">钉钉</a>、<a href="./wechat-work/pipeline.html">企业微信</a>。</p><h2 id="_5-代理配置" tabindex="-1">5. 代理配置 <a class="header-anchor" href="#_5-代理配置" aria-label="Permalink to “5. 代理配置”">​</a></h2><p>当 Jenkins 无法直连机器人 Webhook 地址时，可在全局配置中设置网络代理。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>是否启用代理</td></tr><tr><td><code>type</code></td><td>代理类型：<code>HTTP</code> 或 <code>SOCKS</code></td></tr><tr><td><code>host</code></td><td>代理服务主机，如 <code>127.0.0.1</code></td></tr><tr><td><code>port</code></td><td>代理服务端口，如 <code>1080</code></td></tr></tbody></table><p>代理配置位于 <code>Manage Jenkins</code> -&gt; <code>Lark Notice</code> 页面中的「高级设置」区域。</p><h2 id="_6-详细日志" tabindex="-1">6. 详细日志 <a class="header-anchor" href="#_6-详细日志" aria-label="Permalink to “6. 详细日志”">​</a></h2><p>在 <code>Manage Jenkins</code> -&gt; <code>Lark Notice</code> 页面中的「高级设置」区域，可开启 <code>调试日志</code> 选项。</p><p>开启后，插件会在 Jenkins 系统日志中输出更详细的请求和响应信息，适用于排查消息发送失败等问题。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>排查完毕后建议关闭详细日志，避免日志量过大。</p></div><h2 id="_7-通知触发时机" tabindex="-1">7. 通知触发时机 <a class="header-anchor" href="#_7-通知触发时机" aria-label="Permalink to “7. 通知触发时机”">​</a></h2><p>在 <code>Manage Jenkins</code> -&gt; <code>Lark Notice</code> 页面中的「通知时机」区域，可设置默认通知触发时机；每个任务也可在任务配置中单独覆盖。</p><table tabindex="0"><thead><tr><th>时机</th><th>说明</th></tr></thead><tbody><tr><td>构建开始（START）</td><td>构建启动时触发</td></tr><tr><td>构建成功（SUCCESS）</td><td>构建成功完成时触发</td></tr><tr><td>构建失败（FAILURE）</td><td>构建失败时触发</td></tr><tr><td>构建不稳定（UNSTABLE）</td><td>构建结果为不稳定时触发</td></tr><tr><td>构建中止（ABORTED）</td><td>构建被手动或自动中止时触发</td></tr><tr><td>未构建（NOT_BUILT）</td><td>构建未执行时触发</td></tr></tbody></table><h2 id="_8-配置导入导出" tabindex="-1">8. 配置导入导出 <a class="header-anchor" href="#_8-配置导入导出" aria-label="Permalink to “8. 配置导入导出”">​</a></h2><p>插件支持通过 <code>Manage Jenkins</code> -&gt; <code>Lark Notice</code> 页面右上角的「打开迁移工具」导出或导入 JSON 配置快照。此功能可用于：</p><ul><li>在多个 Jenkins 实例之间同步机器人配置</li><li>备份和恢复配置</li><li>通过脚本批量管理配置</li></ul><p>配置快照包含默认通知时机、机器人、安全策略、重试配置、代理设置等信息，导入时会校验数据格式版本。导入前需要先执行预览，确认新增、更新、移除和保留的机器人数量后再应用。</p>`,42)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};